version: 1
project: shop
dependencies:
  kafka:
    settings: {K: '${endpoint}'}
  db:
    settings: {D: '${endpoint}'}
environments:
  local:
    runtime: podman
    dependencies:
      kafka: {real: {endpoint: 'localhost:9092', image: 'apache/kafka:4.1.0', ports: [9092]}}
      db: {real: {endpoint: 'db.example.com:5432'}}

version: 1
project: shop
dependencies:
  kafka:
    settings: {K: '${endpoint}'}
  orders:
    settings: {O: '${endpoint}'}
environments:
  dev:
    runtime: gcp
    cloud: {modules: ../modules, project: p, region: europe-west1, zone: europe-west1-c, cpu: '2', allowed_cidr_blocks: [10.0.0.0/8]}
    dependencies:
      kafka:
        twin: {image: lawtwin/kafka, version: 0.1.0, conformance: answers, ports: [9092], protocol: tcp, seed: 42, advertise_variable: LAWTWIN_ADVERTISE}
      orders:
        twin: {image: lawtwin/http, version: 0.1.0, conformance: conformant, ports: [8080], contract: petstore}

version: 1
project: shop
dependencies:
  kafka:
    settings:
      KAFKA_BOOTSTRAP_SERVERS: ${endpoint}
environments:
  local:
    runtime: podman
    sync:
      - env_file: {path: config/.env}
      - aws_appconfig: {region: eu-west-1, application: shop, environment: Staging-EU, profile: connections, deployment_strategy: AppConfig.Linear50PercentEvery30Seconds}
      - gcp_parameter_manager: {project: shop-prod, parameter: shop-staging}
      - gcp_parameter_manager: {project: shop-prod, location: europe-west1, parameter: shop-eu}
      - azure_app_configuration: {endpoint: 'https://shop.azconfig.io', prefix: 'shop:'}
      - azure_app_configuration: {endpoint: 'https://shop.azconfig.io', label: green, connection_string_env: SHOP_APPCONFIG}
    config_service: {image: 'ghcr.io/x/config:1', port: 8800}
    dependencies:
      kafka:
        twin: {image: lawtwin/kafka, version: 0.1.0, conformance: c, ports: [9092]}
